{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfbfd;--accent:#6b5df7;--muted:#6b7280;--card:#fff;--glass:rgba(255,255,255,0.6)}
    *{box-sizing:border-box}
    body{font-family:Inter, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial;line-height:1.45;margin:0;background:linear-gradient(180deg,#fbfdff 0%,#fff 40%);color:#111}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 32px;background:url('assets/img/pattern.svg') left top/160px repeat;}
    .brand{display:flex;align-items:center;gap:12px}
    .logo{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#a17bff);display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700}
    nav a{margin-left:18px;color:var(--muted);text-decoration:none;font-weight:600}
    main{max-width:980px;margin:36px auto;padding:0 20px}
    .hero{display:grid;grid-template-columns:1fr;gap:20px;background:var(--card);padding:28px;border-radius:12px;box-shadow:0 6px 20px rgba(15,23,42,0.06)}
    .eyebrow{display:inline-block;background:rgba(107,93,247,0.08);color:var(--accent);padding:6px 10px;border-radius:999px;font-weight:700;font-size:13px}
    h1{margin:6px 0 0;font-size:26px}
    p.lead{margin:12px 0 0;color:var(--muted)}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:18px;margin-top:18px}
    .card{background:var(--card);padding:18px;border-radius:10px;box-shadow:0 8px 30px rgba(12,17,29,0.04)}
    .list{display:flex;flex-direction:column;gap:10px}
    .habit{display:flex;gap:12px;align-items:flex-start}
    .dot{width:44px;height:44px;border-radius:8px;background:linear-gradient(135deg,#ffd6a5,#ffb4a2);display:flex;align-items:center;justify-content:center;font-weight:700;color:#3b2b1f}

    /* Proof Gallery */
    .proof{padding:18px;border-radius:10px;background:linear-gradient(180deg,#fff, #fbfbff);display:grid;gap:12px}
    .testimonial{display:flex;gap:12px;align-items:flex-start}
    .avatar{width:64px;height:64px;border-radius:12px;background:linear-gradient(135deg,#ffecd1,#d4f0ff);display:flex;align-items:center;justify-content:center;font-weight:700;color:#1f2937}
    .quote{font-style:italic;color:#0f1724}
    .controls{display:flex;gap:8px;align-items:center}
    .ctrl-btn{background:var(--glass);border:1px solid rgba(15,23,42,0.06);padding:8px;border-radius:8px;cursor:pointer}
    .badges{display:flex;gap:8px;margin-top:8px}
    .badge{position:relative;padding:8px 10px;border-radius:999px;background:#fff;border:1px solid rgba(15,23,42,0.06);font-weight:700;color:var(--muted);cursor:default}
    .badge[data-tip]:hover::after{content:attr(data-tip);position:absolute;left:50%;transform:translateX(-50%);bottom:calc(100% + 8px);white-space:nowrap;background:#0f1724;color:#fff;padding:8px 10px;border-radius:6px;font-size:13px}

    footer{max-width:980px;margin:28px auto;padding:18px 20px;text-align:center;color:var(--muted)}
    .cta{display:inline-block;margin-top:14px;background:linear-gradient(90deg,var(--accent),#95b3ff);color:#fff;padding:12px 16px;border-radius:10px;text-decoration:none;font-weight:700}

    @media(min-width:900px){.hero{grid-template-columns:1fr 380px}.grid{grid-template-columns:1fr 380px}}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">W</div>
      <div>
        <div style="font-weight:800">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">Wellness coaching for steady progress</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Studio</a>
      <a href="about.html">About</a>
      <a href="services.html">Offerings</a>
      <a href="programs.html">Workshops</a>
      <a href="pricing.html">Plans</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <div>
        <span class="eyebrow">Who we are</span>
        <h1>We design steady habits that stick — without fuss</h1>
        <p class="lead">We help busy people build repeatable day-to-day systems: small, repeatable choices scaffolded into routines that compound into calmer weeks. Outcomes, habits, and simple frameworks — not one-size-fits-all schedules.</p>

        <div class="grid">
          <div class="card">
            <h3>What you get</h3>
            <div class="list">
              <div class="habit"><div class="dot">1</div><div><strong>Clear micro-goals</strong><div class="muted" style="color:var(--muted)">Actions you can finish in 10 minutes or less</div></div></div>
              <div class="habit"><div class="dot">2</div><div><strong>Daily feedback loops</strong><div class="muted" style="color:var(--muted)">Short check-ins to keep momentum</div></div></div>
              <div class="habit"><div class="dot">3</div><div><strong>Frameworks you personalize</strong><div class="muted" style="color:var(--muted)">A template for decisions when life gets noisy</div></div></div>
            </div>
          </div>

          <aside class="card">
            <h4>Fast facts</h4>
            <p style="color:var(--muted)">Cohort-style programs, weekly check-ins, and an emphasis on habits that create measurable consistency.</p>
            <div style="margin-top:12px"><strong>Contact</strong><div style="color:var(--muted);font-size:14px">{{EMAIL}} • {{PHONE}}</div></div>
            <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          </aside>
        </div>
      </div>

      <aside style="padding:12px;border-radius:10px;background:linear-gradient(180deg,#fffbf6,#fff);min-height:120px;display:flex;flex-direction:column;justify-content:center;gap:8px;align-items:flex-start">
        <strong style="font-size:15px;color:var(--accent)">Our promise</strong>
        <div style="font-weight:700">Practical habits you can sustain during busy seasons</div>
        <div style="color:var(--muted)">We measure progress by repeat rate, not perfection.</div>
      </aside>
    </section>

    <section style="margin-top:22px" class="card proof" id="proof">
      <h3 style="margin:0 0 6px">Proof Gallery</h3>
      <div style="color:var(--muted);margin-bottom:6px">Short success stories and the third-party signals that supported them.</div>

      <div id="testimonialWrap" class="testimonial">
        <div class="avatar" id="tAvatar">A</div>
        <div style="flex:1">
          <div style="display:flex;justify-content:space-between;align-items:center">
            <div>
              <div id="tName" style="font-weight:800">Amy R.</div>
              <div id="tMeta" style="color:var(--muted);font-size:13px">Graphic Designer • {{CITY}}, {{STATE}}</div>
            </div>
            <div class="controls">
              <button class="ctrl-btn" id="prev">◀</button>
              <button class="ctrl-btn" id="next">▶</button>
            </div>
          </div>

          <div style="margin-top:10px">
            <div id="tQuote" class="quote">"I learned to split a big goal into tiny anchors. Two months later, I had a morning rhythm I keep on travel days."</div>
            <div class="badges" id="badges"></div>
          </div>
        </div>
      </div>
    </section>

  </main>

  <footer>
    <div>Ready to try a different approach? <a href="{{PRIMARY_CTA_URL}}" class="cta">Start a cohort</a></div>
    <div style="margin-top:8px;color:var(--muted)">Serving {{CITY}}, {{STATE}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
  </footer>

  <script>
    (function(){
      // Proof Gallery data
      const items = [
        {name:'Amy R.', city:'{{CITY}}', state:'{{STATE}}', quote:'I learned to split a big goal into tiny anchors. Two months later, I had a morning rhythm I keep on travel days.', avatar:'A', badges:[{label:'Featured in Serenity Mag',tip:'Article: How small practices beat overwhelm'},{label:'Cohort Grad',tip:'Completed 12-week cohort'}]},
        {name:'Marcus P.', city:'{{CITY}}', state:'{{STATE}}', quote:'The frameworks helped me decide what to keep and what to drop. My energy is steadier, and I don\'t overcommit.', avatar:'M', badges:[{label:'Guest on CalmCast',tip:'Podcast interview about habit design'},{label:'3-month streak',tip:'Tracked daily practice for 90 days'}]},
        {name:'Leila K.', city:'{{CITY}}', state:'{{STATE}}', quote:'Small feedback loops changed everything — enough effort, clear reward, repeat.', avatar:'L', badges:[{label:'Community Leader',tip:'Leads a local micro-accountability group'},{label:'Workshop Host',tip:'Hosted a mini-workshop on decisions'}]}
      ];

      let index = 0;
      const tName = document.getElementById('tName');
      const tMeta = document.getElementById('tMeta');
      const tQuote = document.getElementById('tQuote');
      const tAvatar = document.getElementById('tAvatar');
      const badgesEl = document.getElementById('badges');
      const prev = document.getElementById('prev');
      const next = document.getElementById('next');

      function render(i){
        const item = items[i];
        tName.textContent = item.name;
        tMeta.textContent = item.city + ', ' + item.state;
        tQuote.textContent = item.quote;
        tAvatar.textContent = item.avatar;
        badgesEl.innerHTML = '';
        item.badges.forEach(b=>{
          const bEl = document.createElement('div');
          bEl.className='badge';
          bEl.setAttribute('data-tip', b.tip);
          bEl.textContent = b.label;
          badgesEl.appendChild(bEl);
        })
      }

      prev.addEventListener('click',()=>{ index = (index - 1 + items.length) % items.length; render(index); resetTimer(); });
      next.addEventListener('click',()=>{ index = (index + 1) % items.length; render(index); resetTimer(); });

      let timer = null;
      function auto(){ timer = setInterval(()=>{ index = (index + 1) % items.length; render(index); },5000)}
      function resetTimer(){ if(timer) clearInterval(timer); auto(); }

      render(0); auto();
    })();
  </script>
</body>
</html>"} 
{"path":"services.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Offerings — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfbff;--accent:#ff6b6b;--muted:#5b6b77;--card:#fff}
    body{font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Arial;margin:0;background:linear-gradient(180deg,#ffffff,#fbfdff);color:#111}
    header{display:flex;justify-content:space-between;align-items:center;padding:16px 28px;background:url('assets/img/pattern.svg') right top/180px repeat}
    .logo{width:46px;height:46px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#ff9aa2);color:#fff;display:flex;align-items:center;justify-content:center;font-weight:800}
    nav a{margin-left:16px;color:var(--muted);text-decoration:none;font-weight:700}
    main{max-width:1080px;margin:28px auto;padding:12px}

    .intro{display:flex;gap:20px;align-items:center;justify-content:space-between}
    .intro h1{margin:0;font-size:26px}
    .intro p{color:var(--muted);margin:6px 0 0}

    .offers{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:14px;margin-top:18px}
    .offer{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 8px 28px rgba(14,24,40,0.05)}
    .offer h3{margin:0 0 6px}
    .chips{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}
    .chip{padding:6px 8px;border-radius:999px;background:#f3f4f6;color:var(--muted);font-weight:700}

    /* Pricing Comparator */
    .pricing-card{margin-top:20px;padding:18px;border-radius:12px;background:linear-gradient(180deg,#fff,#fff);display:flex;gap:20px;align-items:center;justify-content:space-between}
    .toggle{display:inline-flex;border-radius:999px;background:#eef2ff;padding:6px}
    .toggle button{border:0;background:transparent;padding:8px 12px;border-radius:999px;cursor:pointer;font-weight:800}
    .toggle .active{background:linear-gradient(90deg,var(--accent),#ff9aa2);color:#fff}
    .price{font-size:28px;font-weight:900}
    .price small{display:block;font-size:12px;color:var(--muted);font-weight:600}

    footer{margin-top:28px;text-align:center;color:var(--muted)}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div class="logo">W</div>
      <div>
        <div style="font-weight:900">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">Cohorts + small-group guidance</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Studio</a>
      <a href="about.html">About</a>
      <a href="services.html">Offerings</a>
      <a href="programs.html">Workshops</a>
      <a href="pricing.html">Plans</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <section class="intro">
      <div>
        <h1>Practical service menu for sustainable change</h1>
        <p>Pick formats that fit your rhythm: private coaching, cohort learning, or one-off clinics for specific habits.</p>
      </div>
      <div>
        <a href="{{PRIMARY_CTA_URL}}" style="background:linear-gradient(90deg,var(--accent),#ff9aa2);padding:10px 14px;border-radius:10px;color:#fff;font-weight:800;text-decoration:none">{{PRIMARY_CTA_LABEL}}</a>
      </div>
    </section>

    <section class="offers">
      <div class="offer">
        <h3>Self-Paced Micro-Course</h3>
        <div style="color:var(--muted);">Bite-sized lessons and templates to build a 3-week rhythm.</div>
        <div class="chips"><span class="chip">Asynchronous</span><span class="chip">Tools</span><span class="chip">Trackers</span></div>
      </div>

      <div class="offer">
        <h3>Cohort: 8-Week Rhythm Lab</h3>
        <div style="color:var(--muted);">Weekly group sessions, small accountability pods, and a habit-focused workbook.</div>
        <div class="chips"><span class="chip">Cohort</span><span class="chip">Live Q&amp;A</span><span class="chip">Templates</span></div>
      </div>

      <div class="offer">
        <h3>Focused Clinic</h3>
        <div style="color:var(--muted);">A single-session workshop to troubleshoot one routine — travel, night, or workday.</div>
        <div class="chips"><span class="chip">90 min</span><span class="chip">Practical</span></div>
      </div>
    </section>

    <section class="pricing-card" aria-label="Pricing comparator">
      <div>
        <div style="font-weight:800">Compare pricing</div>
        <div style="color:var(--muted);font-size:13px">Toggle between monthly plans and package pricing to see the per-person equivalent.</div>
      </div>

      <div style="display:flex;gap:14px;align-items:center">
        <div class="toggle" role="tablist" aria-label="Pricing toggle">
          <button id="optMonthly" class="active">Monthly</button>
          <button id="optPackage">Package</button>
        </div>

        <div style="text-align:right">
          <div class="price" id="priceMain">$0<small id="priceMeta">/month</small></div>
          <div style="color:var(--muted);font-size:13px">Cohort rate shown below</div>
        </div>
      </div>
    </section>

    <section style="margin-top:16px;display:grid;grid-template-columns:1fr 1fr;gap:12px">
      <div class="card offer" style="padding:16px">
        <h3>Monthly Rhythm (team of 1)</h3>
        <div style="color:var(--muted)">Recurring coaching + weekly check-ins.</div>
        <div style="margin-top:12px;font-weight:800">Per month: <span id="m1">$199</span></div>
      </div>

      <div class="card offer" style="padding:16px">
        <h3>Cohort Package (8 weeks)</h3>
        <div style="color:var(--muted)">One-time fee for the full lab experience.</div>
        <div style="margin-top:12px;font-weight:800">Total: <span id="p1">$1199</span></div>
      </div>
    </section>

    <section style="margin-top:18px" class="card">
      <h3>How we frame value</h3>
      <p style="color:var(--muted)">We price for clarity: one recurring option and one packaged learning path. The toggle animates to help you compare monthly billing versus per-cohort cost divided across weeks.</p>
      <div style="margin-top:10px"><a href="{{PRIMARY_CTA_URL}}" style="padding:10px 12px;border-radius:10px;background:linear-gradient(90deg,var(--accent),#ff9aa2);color:#fff;font-weight:800;text-decoration:none">Join a cohort</a></div>
    </section>

  </main>

  <footer>
    <div style="color:var(--muted)">Questions? Email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call {{PHONE}}</div>
  </footer>

  <script>
    (function(){
      // Pricing comparator logic
      const optMonthly = document.getElementById('optMonthly');
      const optPackage = document.getElementById('optPackage');
      const priceMain = document.getElementById('priceMain');
      const priceMeta = document.getElementById('priceMeta');
      const m1 = document.getElementById('m1');
      const p1 = document.getElementById('p1');

      // base values
      const monthlyVal = 199; // per month
      const packageTotal = 1199; // 8-week package
      const packagePerMonthEquivalent = Math.round((packageTotal/2)); // rough per-month equiv for animation

      function animateValue(el,start,end,duration){
        const range = end - start;
        let startTime = null;
        function step(timestamp){
          if(!startTime) startTime = timestamp;
          const progress = Math.min((timestamp - startTime)/duration,1);
          const value = Math.round(start + range*progress);
          el.textContent = '$' + value;
          if(progress < 1) requestAnimationFrame(step);
        }
        requestAnimationFrame(step);
      }

      function setMonthly(){
        optMonthly.classList.add('active');optPackage.classList.remove('active');
        priceMeta.textContent = '/month';
        animateValue(priceMain, parseInt(priceMain.textContent.replace(/\D/g,''))||0, monthlyVal, 600);
        animateValue(m1, parseInt(m1.textContent.replace(/\D/g,''))||0, monthlyVal, 600);
        animateValue(p1, parseInt(p1.textContent.replace(/\D/g,''))||0, packageTotal, 600);
      }
      function setPackage(){
        optPackage.classList.add('active');optMonthly.classList.remove('active');
        priceMeta.textContent = '/month (equiv)';
        animateValue(priceMain, parseInt(priceMain.textContent.replace(/\D/g,''))||0, packagePerMonthEquivalent, 600);
        animateValue(m1, parseInt(m1.textContent.replace(/\D/g,''))||0, Math.round(packageTotal/8), 600);
        animateValue(p1, parseInt(p1.textContent.replace(/\D/g,''))||0, packageTotal, 600);
      }

      optMonthly.addEventListener('click',setMonthly);
      optPackage.addEventListener('click',setPackage);

      // initialize values
      priceMain.textContent = '$' + monthlyVal;
      m1.textContent = '$' + monthlyVal;
      p1.textContent = '$' + packageTotal;
    })();
  </script>
</body>
</html>"} 
