  <script>
    (function(){
      // second pricing comparator instance
      const memBtn = document.getElementById('memBtn');
      const cohortBtn = document.getElementById('cohortBtn');
      const displayNum = document.getElementById('displayNum');
      const displayLabel = document.getElementById('displayLabel');

      const membership = 59; // monthly membership price
      const cohortFee = 399; // per participant cohort fee

      function countTo(el, start, end, duration){
        const range = end - start; let startTime = null;
        function step(ts){
          if(!startTime) startTime = ts;
          const progress = Math.min((ts - startTime)/duration,1);
          const val = Math.round(start + range * progress);
          el.textContent = '$' + val;
          if(progress < 1) requestAnimationFrame(step);
        }
        requestAnimationFrame(step);
      }

      memBtn.addEventListener('click', ()=>{
        memBtn.classList.add('on'); cohortBtn.classList.remove('on');
        displayLabel.textContent = '/month';
        countTo(displayNum, parseInt(displayNum.textContent.replace(/\D/g,''))||0, membership, 500);
      });

      cohortBtn.addEventListener('click', ()=>{
        cohortBtn.classList.add('on'); memBtn.classList.remove('on');
        displayLabel.textContent = '/participant (one-time)';
        countTo(displayNum, parseInt(displayNum.textContent.replace(/\D/g,''))||0, cohortFee, 500);
      });

      // init
      displayNum.textContent = '$' + membership;
    })();
  </script>
